import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { $ } from 'bun';
import { test } from 'bun:test';

test('it publishes the generated changelog', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'changelog-'));

  await $`git init --quiet --initial-branch=main ${dir}`.quiet();
  await $`git remote add origin git@github.com:robin/harbor.git`.cwd(dir).quiet();
  await $`git fetch --quiet origin main && git reset --quiet --hard origin/main`.cwd(dir).quiet();
  await Bun.write(join(dir, 'CHANGELOG.md'), 'generated\n');
  await $`git add CHANGELOG.md && git commit --quiet -m changelog && git push --quiet origin main`.cwd(dir).quiet();
});
